Task 5: Exploratory Questions - Inline Values


Show code
date_start &lt;- min(NETFLIX_DATA$period_start)
date_end   &lt;- max(NETFLIX_DATA$period_end)
n_titles   &lt;- n_distinct(NETFLIX_DATA$title)

# Bridgerton universe (includes spin-offs such as Queen Charlotte)
bridgerton_hours &lt;- NETFLIX_DATA |&gt;
  filter(str_detect(title, "Bridgerton")) |&gt;
  summarise(total = sum(hours_viewed)) |&gt;
  pull(total)

# Stranger Things: the five main seasons only
stranger_things &lt;- NETFLIX_DATA |&gt;
  filter(str_detect(title, "Stranger Things")) |&gt;
  filter_out(str_detect(title, "Beyond")) |&gt;
  filter_out(str_detect(title, "Tales")) |&gt;
  filter_out(str_detect(title, "Fireplace"))

stranger_things_hours &lt;- sum(stranger_things$hours_viewed)

# Top 10 share of 2026H1; "Other Shows" is an aggregate row, not a title
hours_2026h1 &lt;- NETFLIX_DATA |&gt; filter(period == "2026H1")

top10_hours_2026h1 &lt;- hours_2026h1 |&gt;
  filter_out(str_detect(title, "^Other (Shows|Films|Movies)$")) |&gt;
  summarise(hours = sum(hours_viewed), .by = title) |&gt;
  slice_max(hours, n = 10, with_ties = FALSE) |&gt;
  summarise(total = sum(hours)) |&gt;
  pull(total)

top10_share &lt;- top10_hours_2026h1 / sum(hours_2026h1$hours_viewed)

# Global availability: by title and weighted by hours
global_title_share &lt;- NETFLIX_DATA |&gt;
  summarise(global = any(available_globally, na.rm = TRUE), .by = title) |&gt;
  summarise(share = mean(global)) |&gt;
  pull(share)

global_hours_share &lt;- NETFLIX_DATA |&gt;
  summarise(share = sum(hours_viewed[available_globally %in% TRUE]) /
                    sum(hours_viewed)) |&gt;
  pull(share)




